	["answers: mount | mounts | horse | wolf | ram | raptor | kodo | mechanostrider | nightsaber | skeletal horse"] = { "маунт", "маунты", "маунта", "маунтом", "ездовое животное", "ездовой", "скакун", "конь", "коня", "лошадь", "лошади", "волк", "баран", "ящер", "раптор", "кодо", "механодолгоног", "саблезуб", "ночной саблезуб", "скелет коня" },
